#!/usr/bin/env bash
# Area experiments: price each block, so the design is optimised on numbers.
#
#   ./synth/experiment.sh
#
# For every variant in synth/variants/<name>.v it prints cells and area.
# Variants are generated by synth/variants.py.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(dirname "$HERE")"
IMAGE="${IMAGE:-ghcr.io/tinytapeout/openlane2:ihp-v3.0.0.dev23}"
VOL="${VOL:-tt26e-sim}"
PDKVOL="${PDKVOL:-tt26e-pdk}"

docker volume create "$VOL" >/dev/null
tar -C "$ROOT" -cf - . | docker run --rm -i -v "$VOL":/w alpine sh -lc 'rm -rf /w/*; tar -xf - -C /w'

docker run --rm -v "$VOL":/w -v "$PDKVOL":/pdk "$IMAGE" bash -lc '
set -e
cd /w
export PDK_ROOT=/pdk
LIB=$PDK_ROOT/sky130A/libs.ref/sky130_fd_sc_hd/lib/sky130_fd_sc_hd__tt_025C_1v80.lib
python3 synth/variants.py

for v in base nohypot nomulop sincosonly; do
  f=synth/variants/$v.v
  [ -f "$f" ] || continue
  yosys -q -p "
    read_verilog -sv $f
    hierarchy -top tt_um_pryzm_cordic
    synth -top tt_um_pryzm_cordic -flatten
    dfflibmap -liberty $LIB
    abc -liberty $LIB
    opt_clean
    tee -o synth/variants/$v.stat stat -liberty $LIB
  " >/dev/null 2>&1 || { echo "$v: synthesis failed"; continue; }
  echo "=== $v"
  python3 synth/area.py synth/variants/$v.stat | head -3
done
'
